        Object construct(String name)throws Exception{Object e=origin(name).getDeclaredConstructor(world).newInstance(new Object[]{null});strong.add(e);return e;}
        Method own(Object e,String name)throws Exception{return e.getClass().getMethod(name,compound);}
        Object authored(Object e,String name)throws Exception{Object n=fresh();call(putString,n,"id",name);call(putTag,n,"Pos",call(makeD,e,new double[]{1.25,65.5,-2.75}));call(putTag,n,"Motion",call(makeD,e,new double[]{0.125,-0.25,0.5}));call(putTag,n,"Rotation",call(makeF,e,new float[]{35,-10}));call(putFloat,n,"FallDistance",1.5f);call(putShort,n,"Fire",(short)-7);call(putShort,n,"Air",(short)250);call(putByte,n,"OnGround",(byte)-1);for(String key:List.of("Health","HurtTime","DeathTime","AttackTime"))call(putShort,n,key,(short)(key.equals("Health")?-123:key.equals("HurtTime")?-32768:key.equals("DeathTime")?32767:-1));for(String key:List.of("Saddle","Sheared","Color","powered","Angry"))call(putByte,n,key,(byte)-1);call(putByte,n,"Sitting",(byte)1);call(putString,n,"Owner","Owner\u0000\u03a9\ud83d\udc3a");call(putInt,n,"Size",3);call(putInt,n,"Age",999);call(putInt,n,"EggLayTime",1);call(putShort,n,"Fuse",(short)1);call(putByte,n,"ExplosionRadius",(byte)42);call(putInt,n,"Unknown",42);return n;}
        Object typed(Object n)throws Exception{int kind=((Byte)call(type,n)).intValue();Object value=get(n.getClass(),"a",n);if(kind==10){Map<String,Object>fields=new TreeMap<>();for(Map.Entry<?,?>e:((Map<?,?>)value).entrySet())fields.put((String)e.getKey(),typed(e.getValue()));return List.of(kind,fields);}if(kind==9){List<Object>items=new ArrayList<>();for(Object v:(List<?>)value)items.add(typed(v));return List.of(kind,ConstructorJson.map("elementType",get(list,"b",n),"items",items));}if(kind==8)return List.of(kind,units((String)value));if(kind==5||kind==6)return List.of(kind,bits(value));require(kind>=1&&kind<=4,"selected scalar NBT type");return List.of(kind,value);}
